 "content": "def transform(grid):
    out = [row[:] for row in grid]
    # A uniform horizontal divider separates a source panel from its target:
    # copy the non-background object from above to the matching coordinates
    # below, preserving the divider and all other cells.
    for r, row in enumerate(grid):
        if row and all(v == row[0] for v in row):
            sep = r
            break
    else:
        return out
    bg = grid[0][0]
    objs = [(r, c, v) for r in range(sep) for c, v in enumerate(grid[r]) if v != bg]
    if not objs:
        return out
    for r, c, v in objs:
        rr = len(grid) - 1 - (sep - 1 - r)
        if sep < rr < len(grid):
            out[rr][c] = v
    return out
",
